package de.thu.taiko2d.render;

/**
 * 3x3 matrix in homogeneous 2D coordinates (row-major, column vectors: p' = M * p).
 *
 * SCAFFOLD ONLY: the signatures and the TODOs were generated by AI. The student
 * writes the method bodies (that is the contribution to record in CONTRIBUTIONS.md).
 */
public final class Matrix3x3 {
    private final double[] m;   // m[row * 3 + col]

    private Matrix3x3(double[] values) {
        this.m = values;
    }

    public double get(int row, int col) {
        return m[row * 3 + col];
    }

    /** TODO: the identity matrix. */
    public static Matrix3x3 identity() {
        return new Matrix3x3(new double[]{
                1, 0, 0,
                0, 1, 0,
                0, 0, 1
        });
    }

    /** TODO: translation by (tx, ty). */
    public static Matrix3x3 translate(double tx, double ty)
    {
        return new Matrix3x3(new double[]{
                1,  0,  tx,
                0,  1,  ty,
                0,  0,  1
        });
    }

    /** TODO: counter-clockwise rotation by the angle in radians about the origin. */
    public static Matrix3x3 rotate(double radians){
        double cos = Math.cos(radians);
        double sin = Math.sin(radians);
        return new Matrix3x3(new double[]{
                cos,   -sin,    0,
                sin,    cos,    0,
                0,        0,    1
        });
    }

    /** TODO: scaling about the origin. */
    public static Matrix3x3 scale(double sx, double sy) {
        return new Matrix3x3(new double[]{
                sx, 0,  0,
                0,  sy, 0,
                0,  0,  1
        });
    }

    /** TODO: shear; x' = x + shx * y and y' = y + shy * x. */
    public static Matrix3x3 shear(double shx, double shy) {
        return new Matrix3x3(new double[]{
                1,      shx,    0,
                shy,    1,      0,
                0,      0,      1
        });
    }

    /** TODO: returns this * other, so `other` is applied to a point first. */
    public Matrix3x3 multiply(Matrix3x3 other) {
        double[] result = new double[9];
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                result[i*3+j] = this.get(i,0)*other.get(0,j) + this.get(i,1)*other.get(1,j) + this.get(i,2)*other.get(2,j);
            }
        }
        return new Matrix3x3(result);
    }

    /** TODO: applies the matrix to the point (x, y, 1) and returns {x', y'}. */
    public double[] transform(double x, double y) {
        double xRes = m[0]*x + m[1]*y + m[2];
        double yRes = m[3]*x + m[4]*y + m[5];
        return new double[]{xRes, yRes};
    }
}
